{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case fields")
    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError("invalid case field types")
    if any(not isinstance(symbol, str) for symbol in required_symbols):
        raise ValueError("required_symbols must contain strings")
    required = set(required_symbols)
    seen_ids = set()
    by_id = {}
    source_order = {}
    for position, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("missing node field")
        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in seen_ids:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("parent must be a string or null")
        if not isinstance(symbol, str):
            raise ValueError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("depth must be a nonnegative integer")
        if not isinstance(removable, bool):
            raise ValueError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)):
            raise ValueError("utility must be numeric")
        seen_ids.add(node_id)
        by_id[node_id] = node
        source_order[node_id] = position
    roots = [node for node in nodes if node["parent"] is None]
    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]["id"]
    children = {node_id: [] for node_id in by_id}
    for node in nodes:
        parent = node["parent"]
        if parent is not None:
            if parent not in by_id or parent == node["id"]:
                raise ValueError("invalid parent reference")
            children[parent].append(node["id"])
    visited = set()
    stack = [(root_id, 0)]
    while stack:
        node_id, expected_depth = stack.pop()
        if node_id in visited:
            raise ValueError("tree contains a cycle")
        node = by_id[node_id]
        if node["depth"] != expected_depth:
            raise ValueError("depth does not match tree structure")
        visited.add(node_id)
        for child_id in reversed(children[node_id]):
            stack.append((child_id, expected_depth + 1))
    if len(visited) != len(nodes):
        raise ValueError("tree must be connected")
    retained = set(by_id)
    removed = []
    ranked = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in ranked:
        node_id = node["id"]
        if node_id == root_id or not node["removable"] or node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        candidate = retained - {node_id}
        if any(symbol not in {by_id[item]["symbol"] for item in candidate} for symbol in required):
            continue
        retained.remove(node_id)
        removed.append(node_id)
    return {"removed_node_ids": removed, "retained_node_ids": sorted(retained)}"}
